insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_pe_v1'
from (values
('116.27.b.1.A',3,'A seventh grader chains a leap, a quick shuffle and a sprint during a fitness circuit. Combining these skills is practice in...','["linking locomotor movements smoothly", "avoiding movement", "resting between skills", "using only the upper body"]'::jsonb,0,'Locomotor skills can be combined in sequences.','original'),
('116.27.b.1.A',3,'In a dynamic warm-up, which pair is made of locomotor skills?','["kicking and bouncing", "skipping and side-sliding", "catching and throwing", "stretching and holding"]'::jsonb,1,'Skipping and sliding move the body through space.','original'),
('116.27.b.1.B',3,'After a layup, a player lands safely by...','["landing on the toes with locked ankles", "landing stiff-legged", "landing on both feet with bent knees and the chest over the knees", "turning the back to the floor"]'::jsonb,2,'Bent knees and aligned joints reduce injury risk.','original'),
('116.27.b.1.B',3,'Landing on one foot after a hurdle, a runner should...','["keep the leg straight and stiff", "slam the heel down hard", "land on the outside edge of the foot", "land softly on the ball of the foot and roll through to the heel"]'::jsonb,3,'A soft landing absorbs shock.','original'),
('116.27.b.2.A',3,'A player moving between positions in basketball keeps control by...','["staying low with the head up and the weight balanced", "leaning back", "looking at the feet", "keeping the legs straight"]'::jsonb,0,'A balanced posture allows quick changes.','original'),
('116.27.b.2.A',3,'On a balance beam, a student holds a pose longer by...','["moving the head quickly", "fixing the eyes on a point and tightening the core", "holding the breath and swaying", "closing the eyes"]'::jsonb,1,'A focus point and strong core steady the body.','original'),
('116.27.b.2.B',3,'In a net game, good footwork means...','["standing flat footed", "running with crossed legs", "taking small adjusting steps to get under the ball", "waiting for the ball to bounce twice"]'::jsonb,2,'Small steps help position the body.','original'),
('116.27.b.2.B',3,'On offense in an invasion game, a player ''cuts'' by...','["walking toward the bench", "standing still behind a defender", "passing to oneself", "changing direction quickly to get open for a pass"]'::jsonb,3,'A cut creates space.','original'),
('116.27.b.3.A',3,'To improve throwing distance and power, a player should...','["rotate the hips and shoulders as the arm moves forward", "throw only with the wrist", "keep the body square and still", "stand on one leg"]'::jsonb,0,'Rotation transfers force from the legs to the arm.','original'),
('116.27.b.3.A',3,'When throwing accurately, a follow-through should point the throwing hand...','["toward the sky", "at the target", "behind the thrower", "toward the ground"]'::jsonb,1,'The follow-through guides direction.','original'),
('116.27.b.3.B',3,'To catch a thrown object with a glove, the player keeps...','["the glove closed", "the eyes on the runner", "the eyes on the object as it enters the glove", "the arm locked"]'::jsonb,2,'Watching it in helps secure it.','original'),
('116.27.b.3.B',3,'A receiver catching a pass while running should...','["turn away from the pass", "look at defenders instead", "catch with stiff arms", "keep the eyes on the ball and the hands soft"]'::jsonb,3,'Soft hands and focus secure the catch.','original'),
('116.27.b.3.C',3,'When dribbling a basketball against pressure, the dribbler should...','["keep the ball on the side away from the defender", "dribble in the middle with the palm", "hold the ball above the head", "stop dribbling and travel"]'::jsonb,0,'Shielding the ball protects it.','original'),
('116.27.b.3.C',3,'A crossover dribble is used to...','["take a shot", "change direction and get past a defender", "rest", "pass to a teammate"]'::jsonb,1,'The ball moves from one hand to the other.','original'),
('116.27.b.3.D',3,'In a soccer game, a dribbler beats a defender by...','["standing still", "kicking it far ahead", "changing speed and direction with the ball close to the feet", "using only the heel"]'::jsonb,2,'Quick changes make it hard for the defender to react.','original'),
('116.27.b.3.D',3,'A defender trying to stop a dribbler should...','["stand upright with hands up", "lunge in right away", "turn around", "stay low and wait for the ball to be pushed too far ahead"]'::jsonb,3,'Patience helps win the ball.','original'),
('116.27.b.3.E',3,'To kick for distance, a player should...','["swing the kicking leg through and strike the ball with the top of the foot", "stop the leg at contact", "lean back sharply", "use the toe only"]'::jsonb,0,'A full swing and instep contact add distance.','original'),
('116.27.b.3.E',3,'For a controlled short punt, a player should drop the ball...','["behind the body", "close to the foot and kick before it lands", "from head height", "after it bounces twice"]'::jsonb,1,'A short drop gives control.','original'),
('116.27.b.3.F',3,'In a volleyball overhead set, the hands are shaped like...','["a clapping position at the knees", "fists at the chest", "a window or triangle above the forehead", "flat palms at the waist"]'::jsonb,2,'This shape helps direct the ball.','original'),
('116.27.b.3.F',3,'A good volley uses contact that is...','["flat footed with locked wrists", "made with the eyes closed", "done with the back turned", "controlled with the legs lifting and the arms extending"]'::jsonb,3,'Legs and arms work together.','original'),
('116.27.b.3.G',3,'In a tennis forehand, power comes from...','["turning the hips and shoulders into the swing", "holding the racket loosely at the waist", "swinging only the wrist", "not moving the feet"]'::jsonb,0,'Body rotation adds speed.','original'),
('116.27.b.3.G',3,'For a good striking contact, the racket should meet the ball...','["behind the body", "in front of the body at about waist height", "at the feet", "above the head"]'::jsonb,1,'A contact point in front helps accuracy.','original'),
('116.27.b.3.H',3,'A seventh-grade jump rope routine can show agility by including...','["no jumping", "very slow turning only", "quick direction changes and rhythm variations", "standing still"]'::jsonb,2,'Agility is quick, controlled movement.','original'),
('116.27.b.3.H',3,'Which jump rope skill builds coordination and speed?','["tying the rope in a knot", "standing on the rope", "walking beside the rope", "double unders"]'::jsonb,3,'Double unders need timing and speed.','original'),
('116.27.b.4.A',3,'In a team sport, executing a ''give and go'' means...','["passing and then moving into open space to receive the ball back", "passing and standing still", "holding the ball", "passing to the opponent"]'::jsonb,0,'It uses open space.','original'),
('116.27.b.4.A',3,'A defender ''closing space'' on a ball handler should...','["turn and run", "move quickly toward the player while staying balanced", "back away", "stay far from the ball"]'::jsonb,1,'Closing space reduces passing and shooting lanes.','original'),
('116.27.b.4.B',3,'When hitting with a golf club, the golfer controls direction by...','["looking up before contact", "swinging as hard as possible", "keeping the clubface square at impact", "gripping at the very end of the handle with eyes closed"]'::jsonb,2,'Clubface angle sends the ball.','original'),
('116.27.b.4.B',3,'The speed of a swing with a long implement is increased by...','["standing on one foot", "gripping tightly and stiffly", "shortening the swing every time", "a full, smooth body turn"]'::jsonb,3,'A smooth turn builds speed.','original'),
('116.27.b.5',3,'A social dance such as the cha-cha is an example of...','["a rhythmic activity", "an orienteering event", "a net game", "a strength test"]'::jsonb,0,'Rhythmic activities connect movement to music.','original'),
('116.27.b.5',3,'In a rhythmic activity, a group stays in sync by...','["stopping every few seconds", "moving to the same beat and counting steps", "ignoring the music", "each moving at random"]'::jsonb,1,'Shared timing keeps everyone together.','original'),
('116.27.b.6.A',3,'In a net or wall game, a good strategy against a strong opponent is to...','["avoid the net", "hit every shot to the same spot", "alternate short and deep shots to move the opponent", "hit only hard"]'::jsonb,2,'Variety makes defense harder.','original'),
('116.27.b.6.A',3,'In a target game such as archery, the best offensive strategy is to...','["pull the string quickly", "close both eyes", "change the stance every shot", "use a consistent stance and aim point"]'::jsonb,3,'Consistency improves accuracy.','original'),
('116.27.b.6.B',3,'A sequence of game skills for a basketball team goal could be...','["dribble, pass, cut and shoot", "pass to the other team", "stand, wait, stand", "walk off the court"]'::jsonb,0,'Combining skills leads to scoring.','original'),
('116.27.b.6.B',3,'In a flag football play, skills are linked when the quarterback...','["sits down", "takes the snap, steps back and throws to a receiver running a route", "holds the ball and waits", "drops the flag"]'::jsonb,1,'Each skill sets up the next.','original'),
('116.27.b.6.C',3,'Self-responsibility in a game means...','["arguing over every play", "breaking rules when unseen", "calling your own fouls and following rules without being told", "blaming officials"]'::jsonb,2,'Responsible players act fairly on their own.','original'),
('116.27.b.6.C',3,'A player shows sporting behavior by...','["refusing to shake hands", "laughing at errors", "trash-talking", "shaking hands and thanking opponents"]'::jsonb,3,'Respect marks good sportsmanship.','original'),
('116.27.b.7',3,'Leave No Trace outdoor ethics include...','["packing out trash and staying on trails", "building fires anywhere", "leaving food scraps", "picking all the flowers"]'::jsonb,0,'Leave nature as you found it.','original'),
('116.27.b.7',3,'Before a canoe trip, participants should...','["leave the life jacket on shore", "wear a life jacket and learn basic paddling strokes", "swim without supervision", "stand up in the boat"]'::jsonb,1,'Water safety is key.','original'),
('116.27.b.8.A',3,'Analyzing the long-term benefits of exercise shows that it can lower the risk of...','["colds only", "sunburn", "type 2 diabetes and heart disease", "needing sleep"]'::jsonb,2,'Regular activity protects health.','original'),
('116.27.b.8.A',3,'A benefit of strength activities over time is...','["more stress", "weaker bones", "less balance", "stronger bones and muscles"]'::jsonb,3,'Resistance work builds bone density and muscle.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_pe_v1'
from (values
('116.27.b.8.B',3,'To apply FITT to a walking program, a student could increase...','["time by adding 5 minutes each week", "only the music volume", "the number of rest days to seven", "only the shoe size"]'::jsonb,0,'Adjusting time is one FITT change.','original'),
('116.27.b.8.B',3,'In FITT, ''type'' refers to...','["how often it is done", "the kind of exercise performed", "how hard it is", "how long it lasts"]'::jsonb,1,'Type could be jogging, swimming or lifting.','original'),
('116.27.b.8.C',3,'A seventh grader does a sit-and-reach test. Which health-related component does it show?','["agility", "speed", "flexibility", "reaction time"]'::jsonb,2,'It measures hamstring and lower-back flexibility.','original'),
('116.27.b.8.C',3,'A badminton player needs to change direction quickly. Which skill-related component is most important?','["muscular endurance", "flexibility", "body composition", "agility"]'::jsonb,3,'Agility is quick, controlled direction change.','original'),
('116.27.b.9.A',3,'A collaborative fitness plan for a group could include...','["shared goals, a schedule and ways to track each person''s progress", "no plan", "a rule against exercise", "only one person''s goals"]'::jsonb,0,'Planning together keeps everyone on track.','original'),
('116.27.b.9.A',3,'When partners write a fitness plan, they should first...','["decide to skip warm-ups", "identify the areas that need improvement", "choose a random sport", "ignore results"]'::jsonb,1,'Plans target specific needs.','original'),
('116.27.b.9.B',3,'Monitoring a fitness goal means...','["quitting", "setting the goal and forgetting it", "tracking results and adjusting the plan if progress stalls", "never changing the plan"]'::jsonb,2,'Evaluate and adjust.','original'),
('116.27.b.9.B',3,'If a student reaches a fitness goal early, a good next step is to...','["stop exercising", "ignore tracking", "lower all goals", "set a new, slightly harder goal"]'::jsonb,3,'Progression continues improvement.','original'),
('116.27.b.10.A',3,'A balanced daily intake for an active student includes...','["carbohydrates, proteins, fats, fruits and vegetables", "no breakfast", "only sweets", "only protein bars"]'::jsonb,0,'Balance supports energy and recovery.','original'),
('116.27.b.10.A',3,'A good post-workout food choice combines...','["soda with candy", "protein with carbohydrates", "fried food only", "nothing at all"]'::jsonb,1,'It helps muscles recover.','original'),
('116.27.b.10.B',3,'Water is usually the best choice for exercise lasting...','["never", "only in winter", "less than an hour", "longer than three hours only"]'::jsonb,2,'Sports drinks help mainly during long, intense exercise.','original'),
('116.27.b.10.B',3,'A sports drink with electrolytes may help during...','["sleeping", "a short walk in a cool room", "watching TV", "long, intense exercise in the heat"]'::jsonb,3,'Sweat loses sodium and other electrolytes.','original'),
('116.27.b.11.A',3,'A seventh grader going skateboarding should wear...','["a helmet, wrist guards and knee pads", "flip-flops", "no gear", "only socks"]'::jsonb,0,'Protective equipment reduces injuries.','original'),
('116.27.b.11.A',3,'Properly fitted shoes for PE should be...','["untied", "snug with good support and tied", "worn out with no tread", "two sizes too big"]'::jsonb,1,'Proper shoes prevent falls and strains.','original'),
('116.27.b.11.B',3,'A water safety rule is to...','["dive into unknown water", "ignore warning flags", "swim with a buddy and obey lifeguards", "swim alone at night"]'::jsonb,2,'Safe swimming prevents drowning.','original'),
('116.27.b.11.B',3,'A cycling safety precaution is to...','["ride against traffic", "weave between cars", "ride without a helmet", "use hand signals and ride with traffic"]'::jsonb,3,'Predictable riding is safer.','original'),
('116.27.b.12.A',3,'Discussing respect for differences in a PE class could include...','["welcoming classmates of all abilities and backgrounds", "picking teams by popularity", "making jokes about others", "excluding some students"]'::jsonb,0,'Respect creates a safe class.','original'),
('116.27.b.12.A',3,'A respectful teammate treats classmates with different skill levels by...','["refusing to pass", "offering support and including them", "ignoring them", "teasing them"]'::jsonb,1,'Inclusion respects everyone.','original'),
('116.27.b.12.B',3,'Analyzing self-management in sports can show that controlling impulses helps a player...','["argue with officials", "lose focus", "avoid fouls and make better decisions", "break rules more often"]'::jsonb,2,'Self-control improves performance.','original'),
('116.27.b.12.B',3,'A student who stays calm after a bad call is showing...','["carelessness", "aggression", "poor sportsmanship", "self-control"]'::jsonb,3,'Calm responses keep games fair.','original'),
('116.27.b.13.A',3,'Resolving a disagreement over a score is best done by...','["stating your view calmly and listening to the other side", "walking away silently forever", "yelling louder", "shoving"]'::jsonb,0,'Respectful talk solves problems.','original'),
('116.27.b.13.A',3,'When teammates argue, a mediator can help by...','["leaving", "keeping the conversation calm and focused on solutions", "taking sides", "adding insults"]'::jsonb,1,'A mediator guides toward agreement.','original'),
('116.27.b.13.B',3,'I-messages, such as ''I feel upset when the ball is not passed,'' are useful because they...','["blame others", "avoid the problem", "express feelings without blaming", "start fights"]'::jsonb,2,'They keep the conversation respectful.','original'),
('116.27.b.13.B',3,'While settling a disagreement, the speaker should use...','["silence only", "loud accusations", "sarcasm", "a calm tone and clear words"]'::jsonb,3,'Tone affects how people respond.','original'),
('116.27.b.13.C',3,'Showing empathy when a teammate is disappointed includes...','["acknowledging their feelings and offering encouragement", "laughing", "telling them to get over it", "ignoring them"]'::jsonb,0,'Empathy supports others.','original'),
('116.27.b.13.C',3,'Mutual respect between opponents means...','["taunting", "treating each other fairly and politely during and after play", "refusing to compete", "cheating"]'::jsonb,1,'Respect is shown on both sides.','original'),
('116.27.b.14',3,'A student who keeps trying a difficult skill after several failures is showing...','["laziness", "impatience", "perseverance", "carelessness"]'::jsonb,2,'Perseverance means persisting.','original'),
('116.27.b.14',3,'Perseverance helps an athlete by...','["making practice unnecessary", "guaranteeing wins", "ending practice early", "improving skills through repeated effort"]'::jsonb,3,'Effort builds ability.','original'),
('116.27.b.15',3,'Providing constructive feedback to a partner means...','["naming something done well and giving one specific tip", "making fun", "only listing mistakes", "saying nothing"]'::jsonb,0,'Specific, kind feedback helps.','original'),
('116.27.b.15',3,'Accepting feedback from a coach shows...','["anger", "willingness to learn and improve", "weakness", "boredom"]'::jsonb,1,'Open listening speeds growth.','original'),
('116.27.b.16.A',3,'Implementing a plan to be active with technology could mean...','["watching videos all day", "avoiding all activity", "using a step counter to meet a daily goal", "gaming without moving"]'::jsonb,2,'Devices can motivate activity.','original'),
('116.27.b.16.A',3,'A way to make a workout plan visible and trackable is to...','["erase results", "avoid recording", "keep it in your head only", "log minutes and heart rate in an app"]'::jsonb,3,'Tracking supports progress.','original'),
('116.27.b.16.B',3,'Evaluating a self-selected activity for enjoyment means asking...','["whether you like it and will keep doing it", "whether friends picked it", "whether it costs a lot", "whether it is popular online"]'::jsonb,0,'Enjoyment helps keep people active for life.','original'),
('116.27.b.16.B',3,'A person is most likely to stay active for life by choosing activities that...','["they hate", "they enjoy and can do regularly", "are never available", "are too costly to start"]'::jsonb,1,'Enjoyment builds lifelong habits.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
